SELECT count(*) AS error_count
FROM gold.ops_source_freshness
WHERE last_error IS NOT NULL OR lower(last_status) = 'error';

SELECT AVG(temperature_f) AS avg_temperature_f
FROM gold.fct_weather_hourly
WHERE hour_date = DATE '2025-07-04';

SELECT count(*) AS station_count
FROM gold.dim_bike_station
WHERE is_new_jersey = true;
